def k_concatenation_max_sum(arr, k):
    MOD = 10**9 + 7
    full = arr * k                                                          # literally build the fully repeated array
    n = len(full)
    best = 0
    for start in range(n):
        total = 0
        for end in range(start, n):
            total += full[end]                                             # extend the subarray by one and recompute its sum directly
            best = max(best, total)
    return best % MOD


if __name__ == "__main__":
    print(k_concatenation_max_sum([1, 2], 3))

