import java.util.*;

public class Main {
    int kConcatenationMaxSum(int[] arr, int k) {
        final int MOD = 1_000_000_007;
        int n = arr.length * k;
        int[] full = new int[n];
        for (int i = 0; i < n; i++) full[i] = arr[i % arr.length];                 // literally build the fully repeated array
        long best = 0;
        for (int start = 0; start < n; start++) {
            long total = 0;
            for (int end = start; end < n; end++) {
                total += full[end];                                                // extend the subarray by one and recompute its sum directly
                best = Math.max(best, total);
            }
        }
        return (int) (best % MOD);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.kConcatenationMaxSum(new int[]{1, 2}, 3));
    }
}

