import java.util.*;

public class Main {
    int kConcatenationMaxSum(int[] arr, int k) {
        final int MOD = 1_000_000_007;
        long totalSum = 0;
        for (int x : arr) totalSum += x;
        int[] doubled;
        if (k == 1) {
            doubled = arr;
        } else {
            doubled = new int[arr.length * 2];                                     // 2 copies are enough to capture any wrap-around subarray shape
            System.arraycopy(arr, 0, doubled, 0, arr.length);
            System.arraycopy(arr, 0, doubled, arr.length, arr.length);
        }
        long best = 0;                                                              // starting at 0 (not arr[0]) makes the empty subarray a valid, zero-sum baseline
        long current = 0;
        for (int x : doubled) {
            current = Math.max(x, current + x);
            best = Math.max(best, current);
        }
        if (k > 2 && totalSum > 0) {
            best += (long)(k - 2) * totalSum;                                        // extra full copies only ever help if the whole array's sum is positive
        }
        return (int) (best % MOD);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.kConcatenationMaxSum(new int[]{1, -2, 1}, 5));
    }
}

