using namespace std;

int kConcatenationMaxSum(vector<int>& arr, int k) {
    const long long MOD = 1000000007;
    long long totalSum = 0;
    for (int x : arr) totalSum += x;
    vector<int> doubled = arr;
    if (k > 1) doubled.insert(doubled.end(), arr.begin(), arr.end());              // 2 copies are enough to capture any wrap-around subarray shape
    long long best = 0;                                                            // starting at 0 (not arr[0]) makes the empty subarray a valid, zero-sum baseline
    long long current = 0;
    for (int x : doubled) {
        current = max((long long)x, current + x);
        best = max(best, current);
    }
    if (k > 2 && totalSum > 0) {
        best += (long long)(k - 2) * totalSum;                                     // extra full copies only ever help if the whole array's sum is positive
    }
    return (int)(best % MOD);
}

int main() {
    vector<int> arr = {1, -2, 1};
    cout << kConcatenationMaxSum(arr, 5) << endl;
    return 0;
}
